function buildMST(edges, n):
  sort(edges by weight)
  parent = initParent(n)
  mst = []
  for edge in edges:
    if root(parent, edge.u) != root(parent, edge.v):
      link(parent, edge.u, edge.v)
      mst.push(edge)

function root(parent, x):
  if parent[x] != x:
    parent[x] = root(parent, parent[x])
  return parent[x]

function sortColors(arr):
  low = 0
  mid = 0
  high = arr.length - 1
  while mid <= high:
    if arr[mid] == 0:
      swap(arr[low], arr[mid]); low++; mid++
    else if arr[mid] == 2:
      swap(arr[mid], arr[high]); high--
    else:
      mid++

