function kth(arr, k, low, high):
  if low == high:
    return arr[low]
  pivot = partition(arr, low, high)
  if k == pivot:
    return arr[k]
  if k < pivot:
    return kth(arr, k, low, pivot - 1)
  return kth(arr, k, pivot + 1, high)

