function commonSubseq(a, b):
  m = a.length
  n = b.length
  dp = matrix(m + 1, n + 1, 0)
  for i in 1..m:
    for j in 1..n:
      if a[i-1] == b[j-1]:
        dp[i][j] = dp[i-1][j-1] + 1
      else:
        dp[i][j] = max(dp[i-1][j], dp[i][j-1])
  return dp[m][n]

function editDistance(a, b):
  m = a.length
  n = b.length
  dp = matrix(m + 1, n + 1, 0)
  for i in 0..m:
    dp[i][0] = i
  for j in 0..n:
    dp[0][j] = j
  for i in 1..m:
    for j in 1..n:
      cost = a[i-1] == b[j-1] ? 0 : 1
      dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + cost)
  return dp[m][n]

function kmpSearch(text, pattern):
