    pHash = (pHash * 256 + pattern[i]) % 101
    tHash = (tHash * 256 + text[i]) % 101
    h = (h * 256) % 101
  for i in 0..text.length - pattern.length:
    if pHash == tHash and matchAt(text, i, pattern):
      return i
    tHash = rollHash(tHash, text, i, h, pattern.length)

function nextGreater(arr):
  result = array(arr.length, -1)
  stack = []
  for i in 0..arr.length:
    while stack not empty and arr[i] > arr[stack.top]:
      idx = stack.pop()
      result[idx] = arr[i]
    stack.push(i)
