function slidingMax(arr, k):
  deque = []
  result = []
  for i in 0..arr.length:
    while deque not empty and arr[deque.back] <= arr[i]:
      deque.popBack()
    deque.pushBack(i)
    if deque.front <= i - k:
      deque.popFront()
    if i >= k - 1:
      result.push(arr[deque.front])
  return result

