function bucketSort(arr, bucketCount):
  buckets = array(bucketCount, [])
  minVal = min(arr)
  maxVal = max(arr)
  range = maxVal - minVal + 1
  for x in arr:
    idx = floor((x - minVal) / range * bucketCount)
    buckets[idx].push(x)
  for bucket in buckets:
    sort(bucket)
  return flatten(buckets)

function shellSort(arr):
  n = arr.length
  gap = n / 2
  while gap > 0:
    for i in gap..n:
      temp = arr[i]
      j = i
      while j >= gap and arr[j - gap] > temp:
        arr[j] = arr[j - gap]
        j = j - gap
      arr[j] = temp
    gap = gap / 2

