function bidirectionalBFS(start, goal, neighbors):
  front = set(start); back = set(goal)
  depth = 0
  while front not empty and back not empty:
    if front.size > back.size: swap(front, back)
    next = set()
    for node in front:
      for nb in neighbors(node):
        if nb in back: return depth + 1
        if nb not in visited: visited.add(nb); next.add(nb)
    front = next; depth++

