function rangeQuery(tree, node, start, end, left, right):
  if right < start or left > end:
    return neutral
  if left <= start and end <= right:
    return tree[node]
  mid = (start + end) / 2
  return combine(
    rangeQuery(tree, 2*node, start, mid, left, right),
    rangeQuery(tree, 2*node+1, mid+1, end, left, right)
  )

function longestPalindrome(s):
  t = preprocess(s)
  p = array(t.length, 0)
  center = 0; right = 0
  for i in 1..t.length - 1:
    mirror = 2 * center - i
    if i < right: p[i] = min(right - i, p[mirror])
    while matchesPalindrome(t, i, p[i]): p[i]++
    if i + p[i] > right: center = i; right = i + p[i]

function zAlgorithm(s):
  z = array(s.length, 0)
  l = 0
  r = 0
  for i in 1..s.length - 1:
    if i <= r:
      z[i] = min(r - i + 1, z[i - l])
    while i + z[i] < s.length and s[z[i]] == s[i + z[i]]:
      z[i]++
    if i + z[i] - 1 > r:
      l = i
      r = i + z[i] - 1
  return z

function morrisInorder(root):
  current = root
  while current != null:
    if current.left == null:
      visit(current); current = current.right
    else:
      pred = current.left
      while pred.right != null and pred.right != current:
        pred = pred.right
      if pred.right == null:
        pred.right = current; current = current.left
      else:
        pred.right = null; visit(current); current = current.right

