function aStar(start, goal, heuristic):
  open = priorityQueue([(heuristic(start, goal), start)])
  gScore[start] = 0
  while open not empty:
    f, current = open.popMin()
    if current == goal: return gScore[current]
    for neighbor in neighbors(current):
      tentative = gScore[current] + cost(current, neighbor)
      if tentative < gScore.get(neighbor, infinity):
        gScore[neighbor] = tentative
        open.push((tentative + heuristic(neighbor, goal), neighbor))

function combSort(arr):
  n = arr.length
  gap = n
  shrink = 1.3
  sorted = false
  while not sorted:
    gap = max(1, gap / shrink)
    sorted = true
    for i in 0..n - gap:
      if arr[i] > arr[i + gap]:
        swap(arr[i], arr[i + gap])
        sorted = false

function topK(arr, k):
  heap = minHeap()
  for x in arr:
    heap.push(x)
    if heap.size > k:
      heap.pop()
  return heap.toArray()

function dijkstraHeap(adj, source):
  dist = map(source -> 0)
  pq = minHeap([(0, source)])
  while pq not empty:
    d, u = pq.popMin()
    if d > dist[u]:
      continue
    for edge in adj[u]:
      nd = d + edge.weight
      if nd < dist.get(edge.v, infinity):
        dist[edge.v] = nd
        pq.push((nd, edge.v))

function concatRope(left, right):
  if left.weight < right.weight:
    return new Node(left, right, left.length + right.length)
  return new Node(right, left, left.length + right.length)

function indexRope(node, i):
  if i < node.left.length:
    return indexRope(node.left, i)
  return indexRope(node.right, i - node.left.length)

function minCoinsGreedy(coins, amount):
  sort(coins descending)
  count = 0
  for coin in coins:
    while amount >= coin:
      amount = amount - coin
      count = count + 1
  return count
